from ..templates import using
from ..templates import util
from ..entities.local_executor import LocalExecutor  # noqa: F401
from ..entities.local_file_getter import LocalFileGetter  # noqa: F401
from ..entities.local_file_putter import LocalFilePutter  # noqa: F401
from ..entities.ssh_executor import SshExecutor  # noqa: F401
from ..entities.ssh_file_getter import SshFileGetter  # noqa: F401
from ..entities.ssh_file_putter import SshFilePutter  # noqa: F401
from ..entities.k8s_executor import K8sExecutor  # noqa: F401
from ..entities.k8s_file_getter import K8sFileGetter  # noqa: F401
from ..factories.managed_ssh_connection_factory import ManagedSshConnectionFactory  # noqa: F401

Using = using.Using

_remote_creating_template = """\
class {mixin_class_name}(object):

    def _get_managed_ssh_connection(
            self,
            executor_config_name,
            configuration,
            existing_arguments):
        if "managed_ssh_connections" not in existing_arguments:
            existing_arguments["managed_ssh_connections"] = []
        ssh_dict = {{
            (getattr(ssh, "host"), getattr(ssh, "port"), getattr(ssh, "user")): ssh
            for ssh in existing_arguments["managed_ssh_connections"]}}
        cfg = configuration[executor_config_name]
        key = (cfg.get("host"), cfg.get("port", 22), cfg.get("user"))
        if key in ssh_dict:
            return ssh_dict[key]
        else:
            managed_ssh_connection = ManagedSshConnectionFactory().create(
                configuration=cfg,
                existing_arguments={{}})
            existing_arguments["managed_ssh_connections"].append(
                managed_ssh_connection)
            return managed_ssh_connection

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        super({mixin_class_name}, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        managed_ssh_connection = self._get_managed_ssh_connection(
            executor_config_name="{executor_config_name}",
            configuration=configuration,
            existing_arguments=existing_arguments)
"""

_ssh_template_add_on = """\
        resulting_arguments["{attr_name}"] = {created_class_name}(
            managed_ssh_connection=managed_ssh_connection{sudo})
"""

_k8s_template_add_on_common = """\
        tool_executor = SshExecutor(
            managed_ssh_connection=managed_ssh_connection{sudo})
        cfg = configuration["{executor_config_name}"]
        k8s_executor = K8sExecutor(
            tool_executor=tool_executor,
            namespace=cfg.get("namespace"),
            pod=cfg.get("pod"),
            container=cfg.get("container"))
"""

_k8s_template_add_on_executor = """\
        resulting_arguments["{attr_name}"] = k8s_executor
"""

_k8s_template_add_on_file_transfer = """\
        resulting_arguments["{attr_name}"] = {created_class_name}(
            k8s_executor=k8s_executor)
"""

_sudo = """,
            sudo_password=configuration.get("sudo_password")"""

_local_creating_template = """\
class {mixin_class_name}(object):

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        super({mixin_class_name}, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        resulting_arguments["{attr_name}"] = {created_class_name}({sudo})
"""


def Creating(    # noqa: C901
        attr_name,
        class_name,
        executor_config_name="executor"):
    mixin_class_name = "Creating" + util.camel_case(attr_name) + \
                       "Type" + util.camel_case(class_name) + \
                       "From" + util.camel_case(executor_config_name)
    created_class_name = class_name
    if mixin_class_name not in globals():
        sudo = _sudo if created_class_name == "SshExecutor" \
            else _sudo.replace(',', '').strip() if created_class_name == "LocalExecutor" \
            else ""
        if created_class_name in (
                "SshExecutor",
                "SshFileGetter",
                "SshFilePutter"):
            template = _remote_creating_template + _ssh_template_add_on
        elif created_class_name.startswith("K8s"):
            if created_class_name == "K8sExecutor":
                template = _remote_creating_template + _k8s_template_add_on_common + _k8s_template_add_on_executor
            elif created_class_name in (
                    "K8sFileGetter"):
                template = _remote_creating_template + _k8s_template_add_on_common + _k8s_template_add_on_file_transfer
        elif created_class_name in (
                "LocalExecutor",
                "LocalFileGetter",
                "LocalFilePutter"):
            template = _local_creating_template
        else:
            AssertionError(
                "unsupported class name %r" % created_class_name)
        class_string = template.format(
            mixin_class_name=mixin_class_name,
            attr_name=attr_name,
            executor_config_name=executor_config_name,
            created_class_name=created_class_name,
            sudo=sudo)
        exec(class_string, globals())
    return globals()[mixin_class_name]
